package io.ericchernuka.pintprogress; import io.ericchernuka.pintprogress.core.PintFieldLayout; import io.hammerhead.karooext.models.ViewConfig; import org.junit.Assert.assertEquals; import org.junit.Assert.assertNull; import org.junit.Test; import org.w3c.dom.Document; import org.w3c.dom.Node; import java.io.File; import javax.xml.parsers.DocumentBuilderFactory; class PintRemoteViewsLayoutTest { @Test fun `each treatment and alignment selects a static XML layout`() { assertLayoutSet(PintFieldLayout.REGULAR, R.layout.pint_progress_regular_left_view, R.layout.pint_progress_regular_center_view, R.layout.pint_progress_regular_right_view, );         assertLayoutSet(PintFieldLayout.COMPACT, R.layout.pint_progress_compact_left_view, R.layout.pint_progress_compact_center_view, R.layout.pint_progress_compact_right_view, );         assertLayoutSet(PintFieldLayout.PICKER, R.layout.pint_progress_adaptive_left_view, R.layout.pint_progress_adaptive_center_view, R.layout.pint_progress_adaptive_right_view, );         assertLayoutSet(PintFieldLayout.ICON_ONLY, R.layout.pint_progress_adaptive_left_view, R.layout.pint_progress_adaptive_center_view, R.layout.pint_progress_adaptive_right_view, ) };     @Test fun `static wrappers own alignment and include the correct treatment`() { assertWrapper("pint_progress_regular_left_view", "left|center_vertical", "pint_progress_regular_content");         assertWrapper("pint_progress_regular_center_view", "center", "pint_progress_regular_content");         assertWrapper("pint_progress_regular_right_view", "right|center_vertical", "pint_progress_regular_content");         assertWrapper("pint_progress_compact_left_view", "left|center_vertical", "pint_progress_compact_content");         assertWrapper("pint_progress_compact_center_view", "center", "pint_progress_compact_content");         assertWrapper("pint_progress_compact_right_view", "right|center_vertical", "pint_progress_compact_content");         assertWrapper("pint_progress_adaptive_left_view", "left|center_vertical", "pint_progress_adaptive_content");         assertWrapper("pint_progress_adaptive_center_view", "center", "pint_progress_adaptive_content");         assertWrapper("pint_progress_adaptive_right_view", "right|center_vertical", "pint_progress_adaptive_content") };     @Test fun `regular and compact mugs shrink within their original maximums`() { assertResponsiveMug("pint_progress_regular_content", "66dp", "89dp");         assertResponsiveMug("pint_progress_compact_content", "48dp", "65dp") };     @Test fun `counter treatments preserve their distinct XML typography`() { val regular = layoutDocument("pint_progress_regular_content");         assertEquals("2dp", regular.view("pint_count").attribute("android:translationY"));         assertEquals("2dp", regular.view("pint_count_suffix").attribute("android:layout_marginEnd"));         val compact = layoutDocument("pint_progress_compact_content");         assertNull(compact.view("pint_count").attributes.getNamedItem("android:translationY"));         assertEquals("1dp", compact.view("pint_count_suffix").attribute("android:layout_marginEnd"));         listOf(regular, compact).forEach { document -> assertEquals("gone", document.view("pint_count").attribute("android:visibility"));             assertEquals("gone", document.view("pint_count_suffix").attribute("android:visibility")) } };     @Test fun `adaptive mug fills available height and preserves aspect ratio`() { val image = layoutDocument("pint_progress_adaptive_content").view("pint_image");         assertEquals("wrap_content", image.attribute("android:layout_width"));         assertEquals("match_parent", image.attribute("android:layout_height"));         assertEquals("true", image.attribute("android:adjustViewBounds"));         assertEquals("fitCenter", image.attribute("android:scaleType")) };     private fun assertLayoutSet(layout: PintFieldLayout, left: Int, center: Int, right: Int) { assertEquals(left, layout.remoteViewsLayout(ViewConfig.Alignment.LEFT));         assertEquals(center, layout.remoteViewsLayout(ViewConfig.Alignment.CENTER));         assertEquals(right, layout.remoteViewsLayout(ViewConfig.Alignment.RIGHT)) };     private fun assertWrapper(name: String, gravity: String, content: String) { val document = layoutDocument(name);         val root = document.documentElement;         val include = document.getElementsByTagName("include").item(0);         assertEquals("@+id/pint_root", root.attribute("android:id"));         assertEquals(gravity, root.attribute("android:gravity"));         assertEquals("@layout/$content", include.attribute("layout")) };     private fun assertResponsiveMug(name: String, maxWidth: String, maxHeight: String) { val image = layoutDocument(name).view("pint_image");         assertEquals("wrap_content", image.attribute("android:layout_width"));         assertEquals("wrap_content", image.attribute("android:layout_height"));         assertEquals("true", image.attribute("android:adjustViewBounds"));         assertEquals(maxWidth, image.attribute("android:maxWidth"));         assertEquals(maxHeight, image.attribute("android:maxHeight"));         assertEquals("fitCenter", image.attribute("android:scaleType")) };     private fun layoutDocument(name: String): Document = DocumentBuilderFactory.newInstance().newDocumentBuilder().parse(File("src/main/res/layout/$name.xml"));     private fun Document.view(id: String): Node = (0 until getElementsByTagName("*").length).map(getElementsByTagName("*")::item).single { it.attributes?.getNamedItem("android:id")?.nodeValue == "@+id/$id" };     private fun Node.attribute(name: String): String = attributes.getNamedItem(name).nodeValue };